'use strict';

/**
 * Minimal polling bot: echoes back any text it receives.
 *
 *   TELEGRAM_TOKEN=123:ABC node examples/echo-bot.js
 */

const TelegramBot = require('..');

const token = process.env.TELEGRAM_TOKEN;
if (!token) {
  console.error('Set TELEGRAM_TOKEN before running this example.');
  process.exit(1);
}

const bot = new TelegramBot(token, { polling: true });

bot.on('message', (msg) => {
  console.log(`[${msg.chat.id}] ${msg.from.username || msg.from.id}: ${msg.text}`);
});

bot.onText(/^\/start\b/, (msg) => {
  bot.sendMessage(msg.chat.id, 'Hello! Send me anything and I will echo it back.');
});

bot.on('text', (msg) => {
  if (msg.text.startsWith('/')) return;
  bot.sendMessage(msg.chat.id, msg.text);
});

bot.on('polling_error', (err) => console.error('polling_error:', err.message));

'use strict';

/**
 * Inline keyboard with callback handling.
 *
 *   TELEGRAM_TOKEN=123:ABC node examples/keyboard.js
 */

const TelegramBot = require('..');

const token = process.env.TELEGRAM_TOKEN;
if (!token) {
  console.error('Set TELEGRAM_TOKEN before running this example.');
  process.exit(1);
}

const bot = new TelegramBot(token, { polling: true });

bot.onText(/^\/start\b/, (msg) => {
  bot.sendMessage(msg.chat.id, 'Pick an option:', {
    reply_markup: {
      inline_keyboard: [
        [
          { text: 'Option A', callback_data: 'a' },
          { text: 'Option B', callback_data: 'b' },
        ],
        [{ text: 'Open website', url: 'https://core.telegram.org/bots/api' }],
      ],
    },
  });
});

bot.on('callback_query', async (query) => {
  const choice = query.data;
  await bot.answerCallbackQuery(query.id, { text: `You chose ${choice}` });
  await bot.editMessageText(`You chose *${choice}*`, {
    chat_id: query.message.chat.id,
    message_id: query.message.message_id,
    parse_mode: 'MarkdownV2',
  });
});

'use strict';

/**
 * Sending files three ways — Buffer, local path, and remote URL — plus
 * streaming a file down from Telegram.
 *
 *   TELEGRAM_TOKEN=123:ABC CHAT_ID=123456 node examples/send-media.js
 */

const fs = require('fs');
const path = require('path');
const TelegramBot = require('..');

const token = process.env.TELEGRAM_TOKEN;
const chatId = process.env.CHAT_ID;
if (!token || !chatId) {
  console.error('Set TELEGRAM_TOKEN and CHAT_ID before running this example.');
  process.exit(1);
}

const bot = new TelegramBot(token);
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

(async () => {
  // 1. From a remote URL (Telegram fetches it).
  await bot.sendPhoto(chatId, 'https://picsum.photos/600/400', {
    caption: 'Sent from a URL',
  });

  // 2. From a local file path (detected via magic bytes / extension).
  const tmpFile = path.join(require('os').tmpdir(), 'tg-bot-api-example.txt');
  fs.writeFileSync(tmpFile, 'hello from a local file');
  await bot.sendDocument(chatId, tmpFile, { caption: 'Sent from disk' });
  fs.unlinkSync(tmpFile);

  // 3. From an in-memory Buffer.
  const png = Buffer.from(
    'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNkYPhfDwAChwGA60e6kgAAAABJRU5ErkJggg==',
    'base64'
  );
  await bot.sendPhoto(chatId, png, { caption: 'Sent from a Buffer' });

  await sleep(500);

  // 4. Stream a file back down from Telegram.
  const photos = await bot.getUserProfilePhotos(chatId, { limit: 1 });
  if (photos.total_count > 0) {
    const fileId = photos.photos[0].photos[0].file_id;
    const dest = await bot.downloadFile(fileId, require('os').tmpdir());
    console.log('Downloaded to:', dest);
  }
})().catch((err) => {
  console.error('Example failed:', err.message);
  process.exit(1);
});

'use strict';

/**
 * Webhook bot using the library's built-in HTTP server.
 *
 * Telegram only delivers webhooks over HTTPS. The simplest setup is to run
 * this server on plain HTTP behind a TLS-terminating reverse proxy
 * (nginx, caddy, cloudflared, ...) and point WEBHOOK_URL at the proxy.
 *
 * Alternatively, terminate TLS in-process by passing `key` + `cert` (or `pfx`)
 * to the `webHook` options below.
 *
 *   TELEGRAM_TOKEN=123:ABC \
 *   WEBHOOK_URL=https://example.com/tg \
 *   WEBHOOK_PORT=8443 \
 *   node examples/webhook.js
 */

const TelegramBot = require('..');

const token = process.env.TELEGRAM_TOKEN;
if (!token) {
  console.error('Set TELEGRAM_TOKEN before running this example.');
  process.exit(1);
}

const webHookUrl = process.env.WEBHOOK_URL;
if (!webHookUrl) {
  console.error('Set WEBHOOK_URL to a publicly reachable HTTPS endpoint.');
  process.exit(1);
}

const port = Number(process.env.WEBHOOK_PORT || 8443);

const bot = new TelegramBot(token, {
  webHook: {
    port,
    host: '0.0.0.0',
    healthEndpoint: '/healthz',
    // key: fs.readFileSync('/etc/ssl/private/key.pem'),
    // cert: fs.readFileSync('/etc/ssl/certs/cert.pem'),
  },
});

bot.on('message', (msg) => {
  console.log(`[${msg.chat.id}] ${msg.text}`);
  bot.sendMessage(msg.chat.id, 'Webhook received your message.');
});

bot.on('webhook_error', (err) => console.error('webhook_error:', err.message));

bot.setWebHook(webHookUrl, { secret_token: process.env.WEBHOOK_SECRET })
  .then(() => console.log(`Webhook server on :${port}; updates -> ${webHookUrl}`))
  .catch((err) => console.error('Failed to set webhook:', err.message));

const shutdown = () => bot.closeWebHook().then(() => process.exit(0));
process.on('SIGINT', shutdown);
process.on('SIGTERM', shutdown);
